    long long width = hi - lo + 1;
    if (n < 3 || n > 2 * width - 1) {
        puts("-1");
        return 0;
    }
    // Shortest feasible rising run maximizes the first element.
    long long p = max(1LL, n - width);
    string out = to_string(n) + "\n";
    bool first = true;
    auto put = [&](long long v) {
        if (!first) out += ' ';
        first = false;
        out += to_string(v);
    };
    for (long long v = hi - p; v <= hi; v++) put(v);
    for (long long k = 1; k <= n - p - 1; k++) put(hi - k);
    puts(out.c_str());
}

import java.io.*;

public class Main {
    static byte[] buf;
    static int pos;

    static void skip() {
        while (pos < buf.length && buf[pos] <= ' ') pos++;
    }

    static String next() {
        skip();
        int s = pos;
        while (pos < buf.length && buf[pos] > ' ') pos++;
        return new String(buf, s, pos - s);
    }

    static long nextLong() {
        skip();
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] > ' ') r = r * 10 + (buf[pos++] - '0');
        return neg ? -r : r;
    }

    static int nextInt() {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        long n = nextLong(), lo = nextLong(), hi = nextLong();
        long width = hi - lo + 1;
        if (n < 3 || n > 2 * width - 1) {
            System.out.println(-1);
            return;
        }
        // Shortest feasible rising run maximizes the first element.
        long p = Math.max(1, n - width);
        StringBuilder sb = new StringBuilder();
        sb.append(n).append('\n');
        for (long v = hi - p; v <= hi; v++) sb.append(v).append(' ');
        for (long k = 1; k <= n - p - 1; k++) sb.append(hi - k).append(' ');
        sb.setLength(sb.length() - 1);
        System.out.println(sb);
    }
}

package main

import (
	"bufio"
	"io"
	"os"
	"strconv"
)

var data []byte
var p int

func next() []byte {
	for p < len(data) && data[p] <= ' ' {
		p++
	}
	s := p
	for p < len(data) && data[p] > ' ' {
		p++
	}
	return data[s:p]
}

func nextInt() int64 {
	t := next()
	neg := len(t) > 0 && t[0] == '-'
	if neg {
		t = t[1:]
	}
	var r int64
	for _, c := range t {
		r = r*10 + int64(c-'0')
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n, lo, hi := nextInt(), nextInt(), nextInt()
	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()
	width := hi - lo + 1
	if n < 3 || n > 2*width-1 {
		w.WriteString("-1\n")
		return
	}
	// Shortest feasible rising run maximizes the first element.
	p := max(1, n-width)
	w.WriteString(strconv.FormatInt(n, 10) + "\n")
	first := true
	put := func(v int64) {
		if !first {
			w.WriteByte(' ')
		}
		first = false
		w.WriteString(strconv.FormatInt(v, 10))
	}
	for v := hi - p; v <= hi; v++ {
		put(v)
	}
	for k := int64(1); k <= n-p-1; k++ {
		put(hi - k)
	}
	w.WriteByte('\n')
}
